class Solution:
    def solve(self, n, m, a, edges):
        INF = float('inf')

        # Build flow network
        # Source = 0, Sink = n + 1, vertices 1 to n
        source, sink = 0, n + 1
        capacity = [[INF] * (n + 2) for _ in range(n + 2)]
