def solution(input_data):
    lines = input_data.strip().split('\n')
    n = int(lines[0])
    k = [int(x) for x in lines[1].split()]

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    idx = 2
    for _ in range(n - 1):
        u, v = map(int, lines[idx].split())
        adj[u].append(v)
        adj[v].append(u)
        idx += 1

    s = int(lines[idx])

    # BFS to compute distances from s
    dist = [-1] * (n + 1)
    dist[s] = 0
    queue = [s]
    visited = [False] * (n + 1)
    visited[s] = True

    while queue:
        u = queue.pop(0)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                dist[v] = dist[u] + 1
                queue.append(v)

    # Calculate answer: sum of min(k_i, dist[i]) for all vertices except s
    # For vertex s itself, dist[s] = 0, so min(k_s, 0) = 0, which is handled correctly
    total = 0
    for i in range(1, n + 1):
        if dist[i] > 0:
            total += min(k[i - 1], dist[i])

    return str(total) + '\n'


