    query_params = {}  # query_id -> (a, b) or (i) or (q)

    # Track active pairs - store (query_id, a, b)
    active_pairs = []

    for i in range(1, n + 1):
        if i - 1 < len(queries):
            parts = queries[i - 1].split()
            t = int(parts[0])
            query_types[i] = t
            if t == 1:
                a, b = int(parts[1]), int(parts[2])
                query_params[i] = (a, b)
                active_pairs.append((i, a, b))
            elif t == 2:
                idx = int(parts[1])
                query_params[i] = (i, 'REMOVE_IDX', idx)
                # Mark for removal
                if i in query_types and query_types[i] == 1:
                    a_i, b_i = query_params[i] if i in query_params else (0, 0)
                    # We need to handle removal
                    active_pairs = [(qid, a, b) for qid, a, b in active_pairs if qid != idx]
            else:
                q = int(parts[1])
                query_params[i] = (i, 'Q', q)

