Looking at this problem, I need to find the minimum cost to make all elements have a GCD > 1 by either removing a subsegment or changing elements by at most 1.

The key insight is that we only need to consider prime numbers that divide some element `ai` or its neighbors `(ai-1)` or `(ai+1)`. For each candidate prime, I calculate the cost and find the optimal strategy.

**Approach:**
1. Collect all prime factors from each element and its adjacent values (±1)
2. For each prime, calculate the cost to make all elements divisible by it
3. Use Kadane's algorithm to find max removal benefit when all elements are finite
4. Handle INF costs specially by finding the minimum segment covering all INF positions

```python
# Your solution code
def solution(input_string):
    lines = input_string.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    arr = list(map(int, lines[1].split()))

    # Edge case: n=1, element already has gcd > 1
    if n == 1:
        return "0"

    def get_prime_factors(num):
        factors = set()
        d = 2
        temp = num
        while d * d <= temp:
            if temp % d == 0:
                factors.add(d)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            factors.add(temp)
        return factors

    # Collect all candidate primes
    candidates = set()
    for x in arr:
        for dx in [-1, 0, 1]:
            val = x + dx
            if val >= 2:
                candidates.update(get_prime_factors(val))

    def find_min_cost_for_prime(p):
        costs = []
        for x in arr:
            if x % p == 0:
                costs.append(0)
            elif (x - 1) % p == 0 or (x + 1) % p == 0:
                costs.append(b)
            else:
                costs.append(float('inf'))

        return calculate_cost(costs)

    def calculate_cost(costs):
        INF = float('inf')

        # If all costs are infinite, this prime is invalid
        if all(c == INF for c in costs):
            return INF

        # Find indices with infinite cost
        inf_indices = [i for i, c in enumerate(costs) if c == INF]

        if not inf_indices:
            # All finite: use maximum subarray sum (gain from removal)
            dp = [a - c for c in costs]
            max_so_far = -INF
            current_max = 0
            for x in dp:
                current_max = max(x, current_max + x)
                max_so_far = max(max_so_far, current_max)
            return sum(costs) - max(0, max_so_far)

        # Some INF costs exist: must contain all in removal segment
        L = min(inf_indices)
        R = max(inf_indices)

        # Count finite costs outside each possible removal segment
        prefix_sum = [0] * (len(costs) + 1)
        for i in range(len(costs)):
            prefix_sum[i + 1] = prefix_sum[i] + (costs[i] if costs[i] != INF else 0)

        best_cost = INF

        # Expand removal segment optimally
        for start in range(L + 1):
            for end in range(R - 1, -1, -1):
                if start > L or end < R:
                    continue
                removal_len = end - start + 1
                removal_cost = removal_len * a

                # Fixed costs from elements outside [start, end]
                outside_cost = prefix_sum[start] + (prefix_sum[len(costs)] - prefix_sum[end + 1])
                total = removal_cost + outside_cost

                if total < best_cost:
                    best_cost = total

        return best_cost

    # Calculate min cost across all primes
    min_total = INF
    for p in candidates:
        cost = find_min_cost_for_prime(p)
        if cost < min_total:
            min_total = cost

    return str(int(min_total))
