# Your solution code here
def solution(s):
    import sys
    sys.setrecursionlimit(50000)

    lines = s.strip().split('\n')
    n = int(lines[0])

    # Parse pairs (0-indexed internally)
    pairs = []
    for i in range(n):
        a, b = map(int, lines[1+i].split())
        pairs.append((a-1, b-1))  # Convert to 0-indexed

    m = 2 * n
    food = [0] * m

    def check_triple():
        """Check if any three consecutive positions have same food"""
        for i in range(m):
            idx0 = i
            idx1 = (i + 1) % m
            idx2 = (i + 2) % m
            if food[idx0] != 0 and food[idx1] != 0 and food[idx2] != 0:
                if food[idx0] == food[idx1] == food[idx2]:
                    return False
        return True

    def check_couple(idx):
        """Check if couples involving idx have different foods"""
        for a, b in pairs:
            if a == idx or b == idx:
                partner = b if a == idx else a
                # Both assigned and same food is invalid
                if food[partner] != 0 and food[idx] == food[partner]:
                    return False
        return True

    def backtrack(idx):
        if idx == m:
            return check_triple()

        for f in [1, 2]:
            food[idx] = f

            # Partial check: validate if any couple involves idx and its partners are assigned
            if check_couple(idx):
                # Also check triples ending at current and previous positions
                if (idx >= 2 and food[idx] == food[idx-1] == food[idx-2]):
                    pass  # Will be caught in final check_triple

                if (idx >= 1 and idx+1 < m and food[idx] == food[idx-1] and idx+1 < m):
                    pass

                if backtrack(idx + 1):
                    return True

            food[idx] = 0

        return False

    if backtrack(0):
        result = []
        for a, b in pairs:
            result.append(f"{food[a] + 1} {food[b] + 1}")
        return '\n'.join(result)
    else:
        return "-1"
